import { describe, expect, it } from 'vitest';
import { roundHalfEven, round2 } from '../src/common/money';
import cases from './money.cases.json';

/**
 * The expectations are GENERATED by Python (`round(v, d)`), not written by hand — an earlier
 * hand-written table asserted round(2.345, 2) === 2.34 when Python actually gives 2.35, which
 * hid a real bug behind a wrong test.
 */
describe('rounding matches the Python oracle', () => {
  it(`agrees on all ${cases.length} generated cases`, () => {
    const wrong = cases.filter((c) => roundHalfEven(c.v, c.d) !== c.want);
    expect(wrong.slice(0, 5)).toEqual([]);
  });

  it('differs from the JS primitives on exact ties, which is the whole point', () => {
    expect(Math.round(2.5)).toBe(3);          // half away from zero
    expect((2.5).toFixed(0)).toBe('3');       // likewise
    expect(roundHalfEven(2.5)).toBe(2);       // half to even, like Python
    expect(roundHalfEven(2.675, 2)).toBe(2.67);   // not a tie: 2.67499999999999982
    expect(roundHalfEven(2.345, 2)).toBe(2.35);   // not a tie: 2.34500000000000019
  });

  it('round2 is the 2-decimal shorthand', () => {
    expect(round2(10.005)).toBe(10.01);
    expect(round2(0.125)).toBe(0.12);
  });
});
